import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Fotoğraf filtreleri, görselin havasını tek tıkla değiştirir. Vintage, Sepya ve Noir; her biri farklı bir duygu verir.</p>\n<p>Doğru filtre, fotoğrafı yüceltir. Yanlış filtre ise renkleri bozar ve görseli yapay yapar.</p>\n<p>Bu kılavuz, 11 filtre stilini, yoğunluk ayarını ve tutarlı bir görünüm seçmenin yollarını anlatıyor.</p>\n<h2 id=\"what-filters-do\">Fotoğraf filtreleri gerçekte ne yapar?</h2>\n<p>Filtre, renkleri, kontrastı ve parlaklığı birlikte değiştirir. Tek tıkla fotoğrafın havası değişir.</p>\n<p>Filtreler, film görünümünü taklit eder. Vintage, eski film hissi verir; Noir, siyah beyaz drama yaratır.</p>\n<p>Filtre, düzenlemenin kısayoludur. Tek tek ayar yapmak yerine hazır görünüm uygulanır.</p>\n<h2 id=\"eleven-filter-styles\">11 filtre stili</h2>\n<p>Araç, 11 filtre stili sunar. Vintage, Sepya, Noir, Sıcak, Soğuk ve Ters Çevirme başlıca stillerdir.</p>\n<p>Her stil, farklı bir hava verir. Vintage nostaljik, Noir dramatik, Sıcak davetkâr görünür.</p>\n<p>Stilleri tek tek deneyin. Fotoğrafa uyan stili bulmak, denemeyle olur.</p>\n<h2 id=\"filter-intensity\">Filtre yoğunluğu: yüzde 0'dan yüzde 100'e</h2>\n<p>Yoğunluk kaydırıcısı, filtrenin gücünü ayarlar. Yüzde 100 tam etki, yüzde 50 hafif etki verir.</p>\n<p>Yoğunluğu düşük tutun. Yüzde 50-70 arası, çoğu fotoğrafta doğal görünür.</p>\n<p>Yoğunluk yüzde 100'de filtre baskın olur. Fotoğraf, filtrenin arkasında kaybolur.</p>\n<h2 id=\"vintage-default\">Vintage neden varsayılandır?</h2>\n<p>Vintage, en çok kullanılan stildir. Nostaljik his, çoğu fotoğrafta işe yarar.</p>\n<p>Vintage, renkleri yumuşatır ve sıcak ton ekler. Fotoğraf, eski film gibi görünür.</p>\n<p>Varsayılanı değiştirebilirsiniz. Başka bir stili seçin; araç seçiminizi hatırlar.</p>\n<h2 id=\"grayscale-vs-noir\">Gri tonlama ve siyah beyaz Noir</h2>\n<p>Gri tonlama, rengi alır ama tonları korur. Yumuşak ve doğal siyah beyaz verir.</p>\n<p>Noir, kontrastı artırır. Dramatik siyah beyaz; gölgeler derin, parlak alanlar keskindir.</p>\n<p>Seçim, amaca bağlıdır. Yumuşak görünüm için gri tonlama, drama için Noir kullanın.</p>\n<h2 id=\"sepia-vintage-matte-golden\">Sepya, Vintage, Mat Soluk ve Altın Saat</h2>\n<p>Sepya, kahverengi ton ekler. Eski fotoğraf hissi verir; tarihsel görsellerde kullanılır.</p>\n<p>Vintage, sıcak ve yumuşaktır. Nostaljik görünüm için idealdir.</p>\n<p>Mat Soluk, kontrastı düşürür ve renkleri soldurur. Zarif ve sakin his verir.</p>\n<h2 id=\"warm-vs-cool\">Sıcak ve soğuk filtreler</h2>\n<p>Sıcak filtre, turuncu ve sarı ton ekler. Gün batımı ve iç mekân fotoğraflarında iyi görünür.</p>\n<p>Soğuk filtre, mavi ton ekler. Kış ve deniz fotoğraflarında iyi görünür.</p>\n<p>Fotoğrafın havasına göre seçin. Sıcak, davetkâr; soğuk, sakin his verir.</p>\n<h2 id=\"invert-filter\">Ters Çevirme filtresi</h2>\n<p>Ters Çevirme, renkleri tersine çevirir. Negatif film görünümü oluşur.</p>\n<p>Bu filtre, sanatsal işlerde kullanılır. Günlük fotoğraflarda nadiren işe yarar.</p>\n<p>Ters Çevirme, eğlenceli bir efekttir. Deneyin; beğenmezseniz geri alın.</p>\n<h2 id=\"hold-to-view-original\">Orijinali görmek için basılı tutmak</h2>\n<p>Basılı tutma, orijinal fotoğrafı gösterir. Parmağınızı basılı tutun; filtre kalkar.</p>\n<p>Bu özellik, farkı görmenizi sağlar. Filtre gerçekten iyileştiriyor mu, anlarsınız.</p>\n<p>Karşılaştırma, aşırı filtreyi önler. Farkı gördükçe yoğunluğu azaltırsınız.</p>\n<h2 id=\"side-by-side-compare\">Yan yana karşılaştırma</h2>\n<p>Yan yana görünüm, orijinali ve filtreli sürümü birlikte gösterir. Farkı anında görürsünüz.</p>\n<p>Bölünmüş görünüm, görselin bir yarısını orijinal gösterir. Kaydırıcıyla karşılaştırma yapın.</p>\n<p>Karşılaştırma, doğru filtreyi seçmenizi sağlar. Birkaç stili yan yana deneyin.</p>\n<h2 id=\"filters-for-portraits\">Portreler için filtreler</h2>\n<p>Portrelerde hafif filtre kullanın. Yoğunluk yüzde 50-70 arasında olmalıdır.</p>\n<p>Ten renklerini kontrol edin. Filtre, cildi turuncu ya da soluk yapmamalıdır.</p>\n<p>Vintage ve Sıcak, portrelerde iyi görünür. Noir, dramatik portrelerde kullanılır.</p>\n<h2 id=\"filters-for-landscapes\">Manzaralar için filtreler</h2>\n<p>Manzaralarda filtre, gökyüzünü ve yeşili canlandırır. Altın Saat, gün batımında idealdir.</p>\n<p>Yoğunluğu yüzde 60-80 arasında tutun. Manzara, güçlü filtreyi kaldırır.</p>\n<p>Gökyüzünü kontrol edin. Mavi, doğal kalmalıdır; elektrik mavisi yapaydır.</p>\n<h2 id=\"consistent-look\">Tutarlı bir görünüm seçmek</h2>\n<p>Tüm fotoğraflarda aynı filtreyi kullanın. Tutarlılık, profilinizi tanınır kılar.</p>\n<p>Filtre ve yoğunluğu not edin. Aynı ayarları her seferinde kullanın.</p>\n<p>Tutarlılık, markayı güçlendirir. Takipçiler, tarzınızı tanır.</p>\n<h2 id=\"formats-and-export\">Formatlar ve dışa aktarma</h2>\n<p>Filtreli fotoğraflar için JPG uygundur. Küçük dosyalar her cihazda açılır.</p>\n<p>Saydam görseller için PNG kullanın. JPG, saydam köşeleri beyaz yapar.</p>\n<p>Dışa aktarmadan önce önizlemeyi kontrol edin. Filtre ve yoğunluk doğru olmalıdır.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden filtrelemek</h2>\n<p>Filtre aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Bu güvence, özel fotoğraflar için önemlidir. Aile ve müşteri görsellerine rahatça filtre uygulayabilirsiniz.</p>\n<p>Sayfadan ayrılınca veriler silinir. Görselleriniz cihazınızdan ayrılmaz.</p>\n<h2 id=\"common-mistakes\">Filtre kullanırken yaygın hatalar</h2>\n<p>En yaygın hata, aşırı yoğunluktur. Yüzde 100 filtre, fotoğrafı boğar.</p>\n<p>Bir başka hata, tutarsızlıktır. Her fotoğrafta farklı filtre, profili dağınık gösterir.</p>\n<p>Üçüncü hata, orijinali silmektir. Filtreli fotoğraf ayrı bir dosyadır; orijinali saklayın.</p>\n<h2 id=\"filters-for-travel\">Seyahat fotoğrafları için filtreler</h2>\n<p>Seyahat fotoğraflarında Vintage ve Altın Saat iyi görünür. Nostaljik his, anıları güçlendirir.</p>\n<p>Yoğunluğu yüzde 60-80 arasında tutun. Renkler canlı ama doğal görünür.</p>\n<p>Tüm seyahat albümünde aynı filtreyi kullanın. Tutarlı albüm, profesyonel görünür.</p>\n<p>Özetle: filtreyi hafif tutun, tutarlı olun, orijinali saklayın. Uygulama için <a href=\"/tr/blog/fotograf-filtreleri-nasil-uygulanir\">fotoğraf filtreleri nasıl uygulanır</a> yazısına bakın; karşılaştırma için <a href=\"/tr/blog/fotograf-filtreleri-karsilastirildi\">fotoğraf filtreleri karşılaştırması</a> yardımcı olur. Doygunluk için <a href=\"/tr/gorsel-doygunluk-ayarla\">görsel doygunluk düzenleyici</a> hazırdır; araç ise <a href=\"/tr/gorsel-filtreleri\">görsel filtreler</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Portreler için en iyi fotoğraf filtresi hangisi?","answer":"Vintage ve Sıcak filtreler portrelerde iyi görünür; hafif yoğunluk kullanın, yüzde 50-70 arası. Ten renklerini kontrol edin; filtre cildi turuncu ya da soluk yapmamalıdır. Noir, dramatik portrelerde kullanılır."},{"question":"Filtre yoğunluğu kontrolü ne yapar?","answer":"Filtrenin gücünü ayarlar; yüzde 100 tam etki, yüzde 50 hafif etki verir. Yoğunluğu düşük tutun; yüzde 50-70 arası çoğu fotoğrafta doğal görünür. Yüzde 100'de filtre fotoğrafı boğar."},{"question":"Araç neden Vintage seçili başlıyor?","answer":"Çünkü Vintage en çok kullanılan stildir; nostaljik his çoğu fotoğrafta işe yarar. Varsayılanı değiştirebilirsiniz; başka bir stil seçin, araç seçiminizi hatırlar."},{"question":"Aynı fotoğrafa iki filtre uygulayabilir miyim?","answer":"Hayır, araç bir seferde bir filtre uygular. İki filtre isterseniz önce birini uygulayıp indirin, sonra indirilen dosyaya ikinci filtreyi uygulayın. Ancak her uygulama kalite kaybettirir; tek filtre genellikle yeterlidir."},{"question":"Filtreler fotoğrafımın çözünürlüğünü değiştirir mi?","answer":"Hayır. Filtre renkleri, kontrastı ve parlaklığı değiştirir ama piksel sayısını değiştirmez. Çözünürlük aynı kalır. Dosya boyutu format ve kalite ayarına bağlıdır."},{"question":"Kişisel bir fotoğrafa tarayıcı aracında filtre uygulamak güvenli mi?","answer":"Evet. Araç tamamen tarayıcıda çalışır; fotoğraflarınız sunucuya yüklenmez. İş bitince tarayıcı verisi silinir. Özel fotoğrafları güvenle düzenleyebilirsiniz."}];
